formulas.expression:
IF(
  {!IncludeEcologySurvey.value},
  IF(
    AND(
      {!IncludeNaturalEnglandNRWAssent.value},
      {!IncludeOutstandingWayleaves.value},
      {!IncludeHistoricEnglandCadwConsent.value}
    ),
    "6. ",
    IF(
      OR(
        AND({!IncludeNaturalEnglandNRWAssent.value}, {!IncludeOutstandingWayleaves.value}),
        AND({!IncludeNaturalEnglandNRWAssent.value}, {!IncludeHistoricEnglandCadwConsent.value}),
        AND({!IncludeOutstandingWayleaves.value}, {!IncludeHistoricEnglandCadwConsent.value})
      ),
      "5. ",
      IF(
        OR(
          {!IncludeNaturalEnglandNRWAssent.value},
          {!IncludeOutstandingWayleaves.value},
          {!IncludeHistoricEnglandCadwConsent.value}
        ),
        "4. ",
        "3. "
      )
    )
  ),
  NULL
)
